<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';
import {ref,onMounted} from 'vue';const props=defineProps<{csrf?:string;permissions:string[]}>();const data=ref<any>(null),editor=ref<any>(null),busy=ref(false),error=ref(''),message=ref('');const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);
async function api(path='',method='GET',body?:any){const r=await fetch('/pms/api/workflows'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete this action.');return d;}
async function load(){try{data.value=await api();}catch(e){error.value=(e as Error).message;}}
function edit(w?:any){editor.value=w?{...JSON.parse(JSON.stringify(w)),initial_column:w.columns.findIndex((c:any)=>c.is_initial),completed_column:w.columns.findIndex((c:any)=>c.is_completed)}:{name:'',description:'',department_id:null,is_active:true,transition_mode:'any',initial_column:0,completed_column:1,columns:[{name:'To Do',color:'secondary'},{name:'Done',color:'success'}]};}
async function save(){busy.value=true;error.value='';try{const r=await api(editor.value.id?'/'+editor.value.id:'',editor.value.id?'PUT':'POST',editor.value);message.value=r.message;editor.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(w:any){if(!confirm('Delete workflow '+w.name+'?'))return;busy.value=true;try{message.value=(await api('/'+w.id,'DELETE')).message;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function reorder(index:number,step:number){const target=index+step;if(target<0||target>=editor.value.columns.length)return;const a=editor.value.columns;[a[index],a[target]]=[a[target],a[index]];for(const key of ['initial_column','completed_column']){if(editor.value[key]===index)editor.value[key]=target;else if(editor.value[key]===target)editor.value[key]=index;}}
function removeColumn(index:number){editor.value.columns.splice(index,1);for(const key of ['initial_column','completed_column'])editor.value[key]=Math.max(0,editor.value[key]-(editor.value[key]>=index?1:0));}
onMounted(load);
</script>
<template><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice">{{message}}</p><div class="admin-section-heading"><div><div class="small text-muted">ADMINISTRATION</div><h2>Department workflows</h2></div><button v-if="can('department-edit')" class="button primary" @click="edit()">New workflow</button></div><PmsFormDialog v-if="editor" title="Workflow" wide @close="editor=null"><form class="pms-reference-form" @submit.prevent="save"><label>Name<input v-model="editor.name" required maxlength="255"></label><label>Department<select v-model="editor.department_id"><option :value="null">Shared workflow</option><option v-for="d in data?.departments" :key="d.id" :value="d.id">{{d.dept_name}}</option></select></label><label class="full-width">Description<textarea v-model="editor.description" rows="2" maxlength="2000"></textarea></label><label>Movement rule<select v-model="editor.transition_mode"><option value="any">Move to any column</option><option value="adjacent">Adjacent columns only</option></select></label><label class="check"><input type="checkbox" v-model="editor.is_active">Active</label><div class="full-width"><div class="d-flex justify-content-between align-items-center mb-2"><strong>Columns</strong><button class="button" type="button" :disabled="editor.columns.length>=20" @click="editor.columns.push({name:'',color:'secondary'})">Add column</button></div><div class="pms-workflow-column-row" v-for="(c,index) in editor.columns" :key="index"><input v-model="c.name" aria-label="Column name" required maxlength="100"><select v-model="c.color" aria-label="Column color"><option v-for="color in ['secondary','primary','info','warning','danger','success']" :key="color">{{color}}</option></select><label class="check"><input type="radio" name="initial" :value="index" v-model="editor.initial_column">Initial</label><label class="check"><input type="radio" name="completed" :value="index" v-model="editor.completed_column">Completed</label><button type="button" class="btn btn-icon" title="Move up" :disabled="index===0" @click="reorder(Number(index),-1)"><i class="ti ti-arrow-up"></i></button><button type="button" class="btn btn-icon" title="Move down" :disabled="index===editor.columns.length-1" @click="reorder(Number(index),1)"><i class="ti ti-arrow-down"></i></button><button type="button" class="btn btn-icon text-danger" title="Remove column" :disabled="editor.columns.length<=2" @click="removeColumn(Number(index))"><i class="ti ti-trash"></i></button></div><small class="text-muted">Choose one initial column and one completed column.</small></div><div class="editor-actions"><button type="button" class="button" @click="editor=null">Cancel</button><button class="button primary" :disabled="busy">Save workflow</button></div></form></PmsFormDialog><div class="row g-3"><div v-for="w in data?.workflows" :key="w.id" class="col-xl-6"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between"><div><h5 class="mb-1">{{w.name}}</h5><span class="badge bg-label-info">{{w.department?.dept_name||'All departments'}}</span></div><div class="d-flex gap-1"><button v-if="can('department-edit')" class="btn btn-sm btn-icon" title="Edit workflow" @click="edit(w)"><i aria-hidden="true" class="ti ti-edit"></i></button><button v-if="can('department-trash')" class="btn btn-sm btn-icon text-danger" title="Delete workflow" @click="remove(w)" :disabled="busy"><i aria-hidden="true" class="ti ti-trash"></i></button></div></div><p class="text-muted small mt-2">{{w.description}}</p><div class="small text-muted mb-2">{{w.transition_mode==='adjacent'?'Step-by-step movement':'Move to any column'}}</div><div class="d-flex flex-wrap gap-2"><span v-for="c in w.columns" :key="c.id" class="badge" :class="'bg-label-'+c.color">{{c.name}} <span v-if="c.is_initial">&middot; Start</span><span v-if="c.is_completed">&middot; Complete</span></span></div></div></div></div><div v-if="data&&!data.workflows.length" class="col-12"><div class="card"><div class="card-body text-center text-muted py-5">No workflows configured.</div></div></div></div></template>